<script>
(function () {
  // Stat count-up on scroll-into-view.
  if (!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches)) {
    var nums = document.querySelectorAll('.cc-stat-num');
    if (nums.length && 'IntersectionObserver' in window) {
      var ease = function (t) { return 1 - Math.pow(1 - t, 3); };
      var fmt = function (v, comma) { return comma ? Number(v.toFixed(0)).toLocaleString('en-US') : v.toFixed(0); };
      var run = function (el) {
        if (el._done) return;
        el._done = true;
        var to = parseFloat(el.getAttribute('data-cu-to'));
        var to2 = el.getAttribute('data-cu-to2') ? parseFloat(el.getAttribute('data-cu-to2')) : null;
        var sep = el.getAttribute('data-cu-sep') || '';
        var finalTxt = el.getAttribute('data-cu-final') || null;
        var suf = el.getAttribute('data-cu-suf') || '';
        var comma = el.getAttribute('data-cu-comma') === '1';
        var start = performance.now();
        var tick = function (now) {
          var p = Math.min((now - start) / 1500, 1);
          var e = ease(p);
          if (p >= 1 && finalTxt) {
            el.textContent = finalTxt;
          } else {
            var out = fmt(to * e, comma);
            if (to2 != null) out += sep + fmt(to2 * e, comma);
            el.textContent = out + suf;
          }
          if (p < 1) requestAnimationFrame(tick);
        };
        requestAnimationFrame(tick);
      };
      var io = new IntersectionObserver(function (entries) {
        entries.forEach(function (en) {
          if (en.isIntersecting) { run(en.target); io.unobserve(en.target); }
        });
      }, { threshold: 0.5 });
      nums.forEach(function (n) { io.observe(n); });
    }
  }

  // FAQ accordion — one open at a time, +/– sign.
  var btns = document.querySelectorAll('.cc-faq-btn');
  btns.forEach(function (btn) {
    btn.addEventListener('click', function () {
      var wasOpen = btn.classList.contains('is-open');
      btns.forEach(function (b) {
        b.classList.remove('is-open');
        b.querySelector('.cc-faq-sign').innerHTML = '+';
        var a = b.parentElement.querySelector('.cc-faq-a');
        if (a) a.style.display = 'none';
      });
      if (!wasOpen) {
        btn.classList.add('is-open');
        btn.querySelector('.cc-faq-sign').innerHTML = '–';
        var ans = btn.parentElement.querySelector('.cc-faq-a');
        if (ans) ans.style.display = '';
      }
    });
  });

  // Click-to-play YouTube embeds — swaps the thumbnail for a playing iframe in place,
  // instead of sending the visitor to youtube.com.
  function playVideo(el) {
    var id = el.getAttribute('data-vid');
    var title = el.getAttribute('data-title') || 'USMLE Wise video';
    if (!id || el.__played) return;
    el.__played = true;
    var iframe = document.createElement('iframe');
    iframe.src = 'https://www.youtube.com/embed/' + id + '?autoplay=1&rel=0';
    iframe.title = title;
    iframe.allow = 'accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture';
    iframe.allowFullscreen = true;
    iframe.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;border:0;display:block';
    el.innerHTML = '';
    el.appendChild(iframe);
  }
  document.querySelectorAll('.cc-play').forEach(function (el) {
    el.addEventListener('click', function () { playVideo(el); });
    el.addEventListener('keydown', function (e) {
      if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); playVideo(el); }
    });
  });
})();
</script>

